+// input:  [num_heads, total_q, max_seqlen_k]
+// output: [num_heads, total_q, out_len]
+template <typename T>
+__global__ void max_pooling_1d_varlen_kernel(
+    const T* input,
+    T* output,
+    const int* cu_seqlens_q,
+    const int* cu_seqlens_k,
