-template <typename T>
-__global__ void moe_fused_gate_kernel_dynamic(
-    void* input,
-    void* bias,
-    float* output_ptr,
-    int32_t* indices_ptr,
-    int64_t num_rows,
-    int64_t num_experts,
-    int64_t num_expert_group,
-    int64_t topk_group,
